const validUrl = (value) => {
  try { return new URL(value).toString(); } catch { throw new Error('Every request must contain a valid URL.'); }
};

function normalizeTrace(value, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`${label} trace must be a JSON object.`);
  const requests = Array.isArray(value.requests) ? value.requests.map((request) => ({
    url: validUrl(request?.url), method: String(request?.method || 'GET').toUpperCase()
  })) : [];
  const storage = Array.isArray(value.storage) ? value.storage.map((entry) => ({ key: String(entry?.key || '') })).filter((entry) => entry.key) : [];
  return {
    site: String(value.site || 'Unknown site'), capturedAt: String(value.capturedAt || 'Unknown time'),
    browser: String(value.browser || 'Unknown browser'), sequence: String(value.sequence || label), requests, storage
  };
}

const keyFor = (item) => `${item.method || ''} ${item.url || item.key}`;

// Presence-only matching (`some()` against the whole array) is wrong the
// moment a request fires more than once, which trackers routinely do -- a
// pixel loaded once per page section, a script that polls on an interval.
// It missed the case that matters most: the same key present on BOTH sides
// but fewer times after consent. Every "before" copy finds *a* match in
// "after" (the key still exists there), so all of them read as unchanged
// and none as removed, even though two of three firings actually stopped.
// The reverse silently hid a tracker that started firing more often, too.
// This counts occurrences per key instead: the shared count is unchanged,
// and any surplus on either side is added or removed respectively -- so
// "fired 3 times before, 1 time after" now reports 2 removed and 1
// unchanged, not 0 removed.
function diff(before, after) {
  const countByKey = (items) => {
    const counts = new Map();
    for (const item of items) {
      const key = keyFor(item);
      const entry = counts.get(key);
      if (entry) entry.count += 1;
      else counts.set(key, { item, count: 1 });
    }
    return counts;
  };
  const beforeCounts = countByKey(before);
  const afterCounts = countByKey(after);
  const added = [];
  const removed = [];
  const unchanged = [];
  for (const key of new Set([...beforeCounts.keys(), ...afterCounts.keys()])) {
    const beforeEntry = beforeCounts.get(key);
    const afterEntry = afterCounts.get(key);
    const beforeCount = beforeEntry?.count ?? 0;
    const afterCount = afterEntry?.count ?? 0;
    const sharedCount = Math.min(beforeCount, afterCount);
    for (let i = 0; i < sharedCount; i += 1) unchanged.push((afterEntry ?? beforeEntry).item);
    for (let i = sharedCount; i < afterCount; i += 1) added.push(afterEntry.item);
    for (let i = sharedCount; i < beforeCount; i += 1) removed.push(beforeEntry.item);
  }
  return { added, removed, unchanged };
}

export function compareTraces(beforeValue, afterValue) {
  const before = normalizeTrace(beforeValue, 'Before');
  const after = normalizeTrace(afterValue, 'After');
  if (before.site !== 'Unknown site' && after.site !== 'Unknown site' && before.site !== after.site) {
    throw new Error('Before and after traces must refer to the same site.');
  }
  return { before, after, requests: diff(before.requests, after.requests), storage: diff(before.storage, after.storage), comparedAt: new Date().toISOString() };
}

export function reportAsText(report) {
  // Duplicate-count changes come through as repeated entries with the same
  // key (see `diff` above) -- printed one line per instance that would read
  // as a listing bug, not the finding it is. Grouping by key and appending a
  // ×N count keeps "2 removed" legible instead of two identical lines.
  const list = (items) => {
    if (!items.length) return '  - None observed';
    const counts = new Map();
    for (const item of items) counts.set(keyFor(item), (counts.get(keyFor(item)) ?? 0) + 1);
    return [...counts.entries()].map(([key, count]) => `  - ${key}${count > 1 ? ` (×${count})` : ''}`).join('\n');
  };
  return `CONSENT CHANGE RECORD\nCompared: ${report.comparedAt}\nSite: ${report.after.site}\n\nBEFORE\n  Sequence: ${report.before.sequence}\n  Captured: ${report.before.capturedAt}\n  Browser: ${report.before.browser}\n\nAFTER\n  Sequence: ${report.after.sequence}\n  Captured: ${report.after.capturedAt}\n  Browser: ${report.after.browser}\n\nREQUESTS ADDED AFTER CONSENT\n${list(report.requests.added)}\n\nREQUESTS REMOVED AFTER CONSENT\n${list(report.requests.removed)}\n\nSTORAGE KEYS ADDED AFTER CONSENT\n${list(report.storage.added)}\n\nSTORAGE KEYS REMOVED AFTER CONSENT\n${list(report.storage.removed)}\n\nLIMITATION\nThis records observations from the supplied traces only. It does not determine compliance, prove absence in other browsers or regions, or replace professional review.`;
}

tool/har-diff.mjs.text:
// Pure HAR (HTTP Archive) diffing logic — no DOM, no network. Given two
// parsed HAR captures taken before and after a consent choice, reports which
// requests and response cookies appeared or disappeared. Classification
// against trackers.mjs's known-domain list is a disclosed heuristic for
// grouping results, not a determination that an unmatched domain is safe.

import { classifyDomain } from "./trackers.mjs";

function hostnameOf(url) {
  try {
    return new URL(url).hostname.toLowerCase();
  } catch {
    return null;
  }
}

function entriesOf(har) {
  const entries = har?.log?.entries;
  if (!Array.isArray(entries)) {
    throw new Error("Not a HAR file: expected a log.entries array");
  }
  return entries;
}

/** One row per request in a HAR capture. */
function requestRows(har) {
  return entriesOf(har).map((entry, index) => {
    const url = entry.request?.url;
    if (!url) throw new Error(`HAR entry ${index} is missing request.url`);
    return {
      url,
      method: entry.request?.method || "GET",
      hostname: hostnameOf(url),
      startedDateTime: entry.startedDateTime || null,
    };
  });
}

/** Method + origin + path. Query strings and hashes rotate on tracker hits. */
function requestKey(row) {
  try {
    const parsed = new URL(row.url);
    return `${row.method} ${parsed.origin}${parsed.pathname}`;
  } catch {
    return `${row.method} ${row.url}`;
  }
}

/** Cookie names set via Set-Cookie in HAR responses, one row per (hostname, cookie name). */
function cookieRows(har) {
  const rows = [];
  for (const entry of entriesOf(har)) {
    const hostname = hostnameOf(entry.request?.url);
    const cookies = entry.response?.cookies;
    if (!Array.isArray(cookies)) continue;
    for (const cookie of cookies) {
      if (!cookie?.name) continue;
      rows.push({ hostname, name: cookie.name });
    }
  }
  return rows;
}

function cookieKey(row) {
  return `${row.hostname ?? "(unknown host)"}::${row.name}`;
}

function diffByKey(beforeRows, afterRows, keyFn) {
  const beforeKeys = new Set(beforeRows.map(keyFn));
  const afterKeys = new Set(afterRows.map(keyFn));
  // `persisting` is taken from the after-capture and de-duplicated by key: a
  // tracker that fires four times after the consent choice is one finding, not
  // four. It is reported from the after side because that is the capture the
  // user is asking about ("is this still happening now that I rejected?").
  const seen = new Set();
  const persisting = afterRows.filter((row) => {
    const key = keyFn(row);
    if (!beforeKeys.has(key) || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
  return {
    added: afterRows.filter((row) => !beforeKeys.has(keyFn(row))),
    removed: beforeRows.filter((row) => !afterKeys.has(keyFn(row))),
    persisting,
  };
}

/**
 * The document host of a capture, used only to separate "the site's own
 * requests" from third-party ones in the persisting list. Heuristic: the first
 * entry in a HAR is conventionally the top-level document. If that cannot be
 * determined, nothing is treated as first-party, so no row is ever demoted on
 * a guess.
 */
function firstPartyHostname(har) {
  const first = har?.log?.entries?.[0];
  return hostnameOf(first?.request?.url);
}

/**
 * Diffs two HAR captures. Returns added/removed requests (each tagged with a
 * disclosed, non-exhaustive tracker classification), added/removed response
 * cookies, and — the signal a consent check actually turns on — the requests
 * and cookies present in *both* captures, i.e. what carried on unchanged
 * across the consent choice. Throws if either capture is not a HAR log.
 */
export function diffHarCaptures(beforeHar, afterHar) {
  const beforeRequests = requestRows(beforeHar);
  const afterRequests = requestRows(afterHar);
  const {
    added: addedRequests,
    removed: removedRequests,
    persisting: persistingRequests,
  } = diffByKey(beforeRequests, afterRequests, requestKey);

  const beforeCookies = cookieRows(beforeHar);
  const afterCookies = cookieRows(afterHar);
  const {
    added: addedCookies,
    removed: removedCookies,
    persisting: persistingCookies,
  } = diffByKey(beforeCookies, afterCookies, cookieKey);

  const withClassification = (rows) =>
    rows.map((row) => ({ ...row, classification: classifyDomain(row.hostname) }));

  // Third-party is decided per capture-pair, not per row, so that a site whose
  // own host happens to sit on a tracker list is still reported as first-party.
  const documentHost = firstPartyHostname(afterHar) ?? firstPartyHostname(beforeHar);
  const withParty = (rows) =>
    rows.map((row) => ({
      ...row,
      thirdParty: row.hostname != null && row.hostname !== documentHost,
    }));

  const classifiedPersistingRequests = withParty(withClassification(persistingRequests));
  const persistingThirdParty = classifiedPersistingRequests.filter((r) => r.thirdParty);
  const persistingCookiesWithParty = withParty(persistingCookies);

  return {
    summary: {
      beforeRequestCount: beforeRequests.length,
      afterRequestCount: afterRequests.length,
      addedRequestCount: addedRequests.length,
      removedRequestCount: removedRequests.length,
      // Counted on the de-duplicated persisting list, so repeated beacons to
      // the same endpoint do not inflate the headline number.
      persistingRequestCount: classifiedPersistingRequests.length,
      persistingThirdPartyRequestCount: persistingThirdParty.length,
      persistingKnownTrackerRequestCount: persistingThirdParty.filter(
        (r) => r.classification.known,
      ).length,
      addedCookieCount: addedCookies.length,
      removedCookieCount: removedCookies.length,
      persistingCookieCount: persistingCookiesWithParty.length,
    },
    addedRequests: withClassification(addedRequests),
    removedRequests: withClassification(removedRequests),
    persistingRequests: classifiedPersistingRequests,
    addedCookies,
    removedCookies,
    persistingCookies: persistingCookiesWithParty,
    documentHost,
  };
}

tool/trackers.mjs.text:
// A small, manually curated, non-exhaustive list of well-known tracking and
// advertising domains, used only to *group* results for a human reviewer.
// Absence from this list is not evidence that a domain does not track — it
// only means this list has not been updated to include it. Every unmatched
// domain still appears in the diff report as "unclassified", never dropped.

const CATEGORIZED_SUFFIXES = [
  ["google-analytics.com", "analytics"],
  ["analytics.google.com", "analytics"],
  ["googletagmanager.com", "analytics"],
  ["doubleclick.net", "advertising"],
  ["googlesyndication.com", "advertising"],
  ["googleadservices.com", "advertising"],
  ["facebook.net", "advertising"],
  ["facebook.com", "advertising"],
  ["ads-twitter.com", "advertising"],
  ["analytics.twitter.com", "analytics"],
  ["linkedin.com", "advertising"],
  ["bat.bing.com", "advertising"],
  ["hotjar.com", "session-recording"],
  ["fullstory.com", "session-recording"],
  ["clarity.ms", "session-recording"],
  ["mouseflow.com", "session-recording"],
  ["mixpanel.com", "analytics"],
  ["segment.io", "analytics"],
  ["segment.com", "analytics"],
  ["amplitude.com", "analytics"],
  ["hubspot.com", "advertising"],
  ["hs-analytics.net", "analytics"],
  ["criteo.com", "advertising"],
  ["adroll.com", "advertising"],
  ["taboola.com", "advertising"],
  ["outbrain.com", "advertising"],
  ["tiktok.com", "advertising"],
  ["snapchat.com", "advertising"],
  ["pinterest.com", "advertising"],
  ["yandex.ru", "analytics"],
  ["quantserve.com", "analytics"],
  ["scorecardresearch.com", "analytics"],
];

/**
 * Classifies a hostname by suffix match against the curated list above.
 * Returns `{ known: true, category }` or `{ known: false, category:
 * "unclassified" }`. `known: false` must never be read as "not tracking" —
 * it means "not in this list", and the caller is responsible for showing
 * unclassified rows rather than hiding them.
 */
export function classifyDomain(hostname) {
  if (!hostname) return { known: false, category: "unclassified" };
  const lower = hostname.toLowerCase();
  for (const [suffix, category] of CATEGORIZED_SUFFIXES) {
    if (lower === suffix || lower.endsWith(`.${suffix}`)) {
      return { known: true, category };
    }
  }
  return { known: false, category: "unclassified" };
}

export const KNOWN_TRACKER_DOMAIN_COUNT = CATEGORIZED_SUFFIXES.length;

tool/usage.mjs.text:
// Local-first, aggregate-only usage counting, per portfolio/usage/usage.yaml:
// count events, never people. No IDs, no IPs, no content, no file names or
// URLs from a capture — just an event name and a day, kept in this browser's
// own localStorage. Nothing is sent anywhere; there is no server for it to
// go to. Off-switchable, and honors Do Not Track / Global Privacy Control.

const STORAGE_KEY = "consent-change-record:usage-events";
const OPT_OUT_KEY = "consent-change-record:usage-opt-out";

function hasStorage() {
  try {
    return typeof localStorage !== "undefined";
  } catch {
    return false;
  }
}

function honorsBrowserSignal() {
  try {
    return navigator?.doNotTrack === "1" || navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function isUsageCountingEnabled() {
  if (!hasStorage()) return false;
  if (honorsBrowserSignal()) return false;
  try {
    return localStorage.getItem(OPT_OUT_KEY) !== "1";
  } catch {
    return false;
  }
}

export function setUsageCountingEnabled(enabled) {
  if (!hasStorage()) return;
  try {
    if (enabled) localStorage.removeItem(OPT_OUT_KEY);
    else localStorage.setItem(OPT_OUT_KEY, "1");
  } catch {
    // storage unavailable (private mode, quota) — nothing to do
  }
}

/** Records that `eventName` happened today. Aggregate count only; no payload beyond the event name and the day. */
export function recordEvent(eventName) {
  if (!isUsageCountingEnabled()) return;
  try {
    const day = new Date().toISOString().slice(0, 10);
    const raw = localStorage.getItem(STORAGE_KEY);
    const events = raw ? JSON.parse(raw) : {};
    const key = `${eventName}:${day}`;
    events[key] = (events[key] || 0) + 1;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(events));
  } catch {
    // storage unavailable — counting is best-effort only
  }
}

/** Returns the raw local event counts, for the user's own inspection. */
export function readLocalUsage() {
  if (!hasStorage()) return {};
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

usage.mjs.text:
export function recordUsage(storage, optedOut, navigatorLike = globalThis.navigator) {
  // The visitor's stored choice, consulted before anything else: the
  // caller passes its own idea of it, and on most pages here that came
  // from a control that had forgotten.
  if (readOptOut(storage)) return;
  if (optedOut || !storage) return;
  if (navigatorLike && (navigatorLike.doNotTrack === '1' || navigatorLike.globalPrivacyControl)) return;
  try {
    const current = Number(storage.getItem('consent-change-record:comparisons') || 0);
    storage.setItem('consent-change-record:comparisons', String(current + 1));
  } catch { /* Browser storage can be unavailable; the product must still work. */ }
}

// The opt-out choice is kept in its own key, not in the counters:
// opting out *removes* the counters, so a flag stored inside them would
// be deleted by the very act it records. The recorder above consults it
// directly, so the promise does not depend on a caller remembering to
// pass the choice in.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem('consent-change-record:comparisons-opt-out') === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem
  // that throws on a full quota skips the delete entirely, and the
  // visitor gets neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem('consent-change-record:comparisons'); } catch { /* storage is optional */ }
    try { storage.setItem('consent-change-record:comparisons-opt-out', '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem('consent-change-record:comparisons-opt-out'); } catch { /* storage is optional */ }
  }
}
